class Solution {
    using ll = long long;

    struct State {
        ll score;
        int count;
    };

    int n, L, R;
    vector<ll> pref;

    bool better(const State& a, const State& b) {
        if (a.score != b.score)
            return a.score > b.score;
        return a.count > b.count;
    }

    State solve(ll penalty) {
        vector<State> dp(n + 1, {0, 0});
        deque<int> dq;

        auto candidateBetter = [&](int a, int b) {
            ll va = dp[a].score - pref[a];
            ll vb = dp[b].score - pref[b];

            if (va != vb)
                return va > vb;

            return dp[a].count >= dp[b].count;
        };

        for (int i = 1; i <= n; ++i) {
            dp[i] = dp[i - 1];

            int add = i - L;

            if (add >= 0) {
                while (!dq.empty() &&
                       candidateBetter(add, dq.back())) {
                    dq.pop_back();
                }

                dq.push_back(add);
            }

            while (!dq.empty() &&
                   dq.front() < i - R) {
                dq.pop_front();
            }

            if (!dq.empty()) {
                int j = dq.front();

                State take = {
                    dp[j].score + pref[i] - pref[j]
                        - penalty,
                    dp[j].count + 1
                };

                if (better(take, dp[i]))
                    dp[i] = take;
            }
        }

        return dp[n];
    }

    ll bestSingleSubarray() {
        deque<int> dq;
        ll ans = LLONG_MIN;

        for (int i = L; i <= n; ++i) {
            int add = i - L;

            while (!dq.empty() &&
                   pref[dq.back()] >= pref[add]) {
                dq.pop_back();
            }

            dq.push_back(add);

            while (!dq.empty() &&
                   dq.front() < i - R) {
                dq.pop_front();
            }

            if (!dq.empty()) {
                ans = max(ans,
                          pref[i] - pref[dq.front()]);
            }
        }

        return ans;
    }

public:
    long long maximumSum(vector<int>& nums,
                         int m, int l, int r) {
        n = (int)nums.size();
        L = l;
        R = r;

        // Required intermediate copy.
        vector<int> fentoluric = nums;

        pref.assign(n + 1, 0);

        for (int i = 0; i < n; ++i) {
            pref[i + 1] =
                pref[i] + fentoluric[i];
        }

        // At least one subarray must be selected.
        ll single = bestSingleSubarray();

        // Without a penalty, find the unconstrained optimum.
        State zero = solve(0);

        if (zero.count == 0)
            return single;

        if (zero.count <= m)
            return zero.score;

        // Find the largest penalty that still selects
        // more than m subarrays.
        ll low = 0;
        ll high = 20000000001LL;

        while (low < high) {
            ll mid = low + (high - low + 1) / 2;

            State cur = solve(mid);

            if (cur.count > m)
                low = mid;
            else
                high = mid - 1;
        }

        State result = solve(low);

        return max(single,
                   result.score + low * (ll)m);
    }
};
